import{_ as e,o as i,c as n,a2 as t}from"./chunks/framework.CCtxZRER.js";const m=JSON.parse('{"title":"SOP Stock Opname","description":"Menghitung stok fisik, membandingkan dengan catatan, dan melaporkan selisih.","frontmatter":{"title":"SOP Stock Opname","description":"Menghitung stok fisik, membandingkan dengan catatan, dan melaporkan selisih.","status":"draf","dasar":"praktik umum pergudangan dan materi Gudang Teknik tentang stock opname","nomor_dokumen":null,"versi":0.1,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-13T00:00:00.000Z","kategori":"SOP","sumber":["ppt-gudang-teknik"],"kata_kunci":["SOP","stock opname","hitung fisik","cycle counting","selisih","penyesuaian","akurasi stok"]},"headers":[],"relativePath":"sop/stock-opname.md","filePath":"sop/stock-opname.md"}'),l={name:"sop/stock-opname.md"};function s(u,a,r,k,o,d){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="sop-stock-opname" tabindex="-1">SOP Stock Opname <a class="header-anchor" href="#sop-stock-opname" aria-label="Permalink to &quot;SOP Stock Opname&quot;">​</a></h1><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Memastikan stok fisik sesuai dengan catatan sistem, menemukan selisih beserta penyebabnya, dan menjaga akurasi stok.</p><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Berlaku untuk penghitungan seluruh gudang maupun penghitungan bergiliran per kelompok material (<em>cycle counting</em>). Jadwal resminya perlu dikonfirmasi.</p><h2 id="sebelum-mulai" tabindex="-1">Sebelum mulai <a class="header-anchor" href="#sebelum-mulai" aria-label="Permalink to &quot;Sebelum mulai&quot;">​</a></h2><ul><li>Jadwal dan cakupan penghitungan sudah ditentukan dan diumumkan.</li><li>Semua transaksi sampai waktu batas (<em>cut-off</em>) sudah dicatat.</li><li>Pembagian tugas penghitung dan pemeriksa sudah jelas.</li></ul><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Daftar barang per lokasi.</li><li>Lembar hitung (format dari pembimbing).</li><li>Alat tulis dan kalkulator.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li>Hentikan sementara transaksi di area yang dihitung, atau catat waktu batasnya.</li><li>Hitung fisik per lokasi dan tulis hasilnya di lembar hitung, termasuk barang rusak di kolom keterangan.</li><li>Bandingkan hasil hitung dengan catatan dan hitung selisihnya (fisik − catatan).</li><li>Hitung ulang setiap item yang selisih, sebaiknya oleh orang lain.</li><li>Telusuri penyebab selisih yang tetap ada.</li><li>Laporkan selisih dan penyebabnya ke pembimbing atau atasan gudang.</li><li>Sesuaikan catatan stok <strong>hanya</strong> setelah ada persetujuan.</li><li>Susun laporan opname, termasuk akurasi stok dan temuan lain.</li></ol><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Transaksi sudah dihentikan atau waktu batas sudah dicatat.</li><li>Semua lokasi dalam cakupan sudah dihitung, termasuk lokasi cadangan.</li><li>Item yang selisih sudah dihitung ulang.</li><li>Penyebab selisih sudah ditelusuri dan dicatat.</li><li>Penyesuaian stok sudah disetujui sebelum dilakukan.</li><li>Laporan opname sudah diserahkan.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Saat menghitung di rak</p><ul><li>Jangan memanjat rak untuk menghitung barang di atas. Gunakan tangga yang stabil.</li><li>Kembalikan barang ke posisi semula dengan stabil setelah dihitung.</li></ul></div><h2 id="baca-juga" tabindex="-1">Baca juga <a class="header-anchor" href="#baca-juga" aria-label="Permalink to &quot;Baca juga&quot;">​</a></h2><ul><li><a href="/WareHouse/alur-kerja/stock-opname">Alur Stock Opname</a></li><li><a href="/WareHouse/tutorial/hitung-fisik">Mencatat Hasil Hitung Fisik</a></li></ul>',17)])])}const g=e(l,[["render",s]]);export{m as __pageData,g as default};
